"use client";

import { useState } from "react";
import { PackageCheck } from "lucide-react";
import Modal from "../ui/Modal";
import Button from "../ui/Button";
import type { DrugStock, PurchaseOrder, ReceiveValues } from "@/lib/pharmacy-api";
import { monthsFromNow } from "@/lib/pharmacy-data";

const input =
  "mt-1 w-full rounded-md border border-surface-border px-3 py-2 text-sm text-slate-800 outline-none placeholder:text-slate-300 focus:border-brand-teal";
const label = "text-[11px] font-semibold uppercase tracking-wide text-slate-400";

/**
 * Goods in. The batch number is generated by the server (e.g. CEF-2610-1)
 * unless the pharmacist types the manufacturer's lot number from the box.
 */
export default function ReceiveStockModal({
  open,
  onClose,
  drugs,
  purchaseOrder,
  onSubmit,
}: {
  open: boolean;
  onClose: () => void;
  drugs: DrugStock[];
  purchaseOrder?: PurchaseOrder | null;
  onSubmit: (v: ReceiveValues) => Promise<boolean>;
}) {
  return (
    <Modal
      open={open}
      onClose={onClose}
      title={purchaseOrder ? `Receive ${purchaseOrder.poNumber}` : "Receive Stock"}
      description={purchaseOrder ? `${purchaseOrder.drugName} · ${purchaseOrder.supplier}` : "Add a delivery to the shelf"}
      icon={PackageCheck}
      size="sm"
    >
      {open && (
        <ReceiveForm
          key={purchaseOrder?.id ?? "free"}
          drugs={drugs}
          purchaseOrder={purchaseOrder}
          onClose={onClose}
          onSubmit={onSubmit}
        />
      )}
    </Modal>
  );
}

function ReceiveForm({
  drugs,
  purchaseOrder,
  onClose,
  onSubmit,
}: {
  drugs: DrugStock[];
  purchaseOrder?: PurchaseOrder | null;
  onClose: () => void;
  onSubmit: (v: ReceiveValues) => Promise<boolean>;
}) {
  const [drugId, setDrugId] = useState(purchaseOrder?.drugId ?? "");
  const [qty, setQty] = useState(purchaseOrder ? String(purchaseOrder.quantity) : "");
  const [expiry, setExpiry] = useState(monthsFromNow(12));
  const [lot, setLot] = useState("");
  const [supplier, setSupplier] = useState(purchaseOrder?.supplier ?? "");
  const [saving, setSaving] = useState(false);

  const drug = drugs.find((d) => d.id === drugId);
  const today = new Date().toISOString().slice(0, 10);
  const invalid = !drugId || !qty || Number(qty) <= 0 || !expiry || expiry <= today;

  async function submit() {
    if (invalid) return;
    setSaving(true);
    const ok = await onSubmit({
      drugId: purchaseOrder ? undefined : drugId,
      quantity: Number(qty),
      expiryDate: expiry,
      batchNo: lot.trim() || undefined,
      supplier: supplier.trim() || undefined,
    });
    setSaving(false);
    if (ok) onClose();
  }

  return (
    <div className="space-y-3">
      {!purchaseOrder && (
        <div>
          <label className={label}>Drug</label>
          <select
            value={drugId}
            onChange={(e) => {
              setDrugId(e.target.value);
              setSupplier(drugs.find((d) => d.id === e.target.value)?.supplier ?? "");
            }}
            className={input}
          >
            <option value="">Select a drug…</option>
            {drugs.map((d) => (
              <option key={d.id} value={d.id}>
                {d.name} ({d.onHand} {d.unit} on hand)
              </option>
            ))}
          </select>
        </div>
      )}
      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className={label}>Quantity{drug ? ` (${drug.unit})` : ""}</label>
          <input type="number" min={1} value={qty} onChange={(e) => setQty(e.target.value)} className={input} />
        </div>
        <div>
          <label className={label}>Expiry date</label>
          <input type="date" min={today} value={expiry} onChange={(e) => setExpiry(e.target.value)} className={input} />
        </div>
      </div>
      <div>
        <label className={label}>Manufacturer lot no. (optional)</label>
        <input
          value={lot}
          onChange={(e) => setLot(e.target.value)}
          placeholder="Leave blank to auto-generate"
          className={input}
        />
        <p className="mt-1 text-[11px] text-slate-400">
          {lot.trim()
            ? "This lot number will be recorded as the batch."
            : `A batch number like ${(drug?.code.replace(/[^A-Za-z]/g, "").slice(0, 3) ?? "AML").toUpperCase()}-${new Date().toISOString().slice(2, 4)}${new Date().toISOString().slice(5, 7)}-1 is generated for you.`}
        </p>
      </div>
      <div>
        <label className={label}>Supplier</label>
        <input value={supplier} onChange={(e) => setSupplier(e.target.value)} className={input} />
      </div>
      {expiry && expiry <= today && <p className="text-[11px] text-status-red">Expiry must be in the future.</p>}
      <div className="flex justify-end gap-2 border-t border-surface-border pt-3">
        <Button variant="secondary" onClick={onClose} disabled={saving}>
          Cancel
        </Button>
        <Button variant="primary" onClick={submit} loading={saving} disabled={invalid}>
          Receive into Stock
        </Button>
      </div>
    </div>
  );
}
